    const idx = indices.data.find(i=>i.name==='BTC_USDT'), spot = gateNumber(idx?.index_price), indexTime = gateNumber(idx?.index_time)*1000;
    const now = clock(), time = Math.min(indexTime, catalogue.time, indices.time);
