      if (row.stickType !== 0 || row.status !== 2 || row.direction !== direction ||
          row.productTokenId !== 1 || row.productTokenName !== 'BTC' || row.tradeTokenId !== tradeTokenId ||
          row.tradeTokenName !== coin) continue;
